(()=>{
"use strict";
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const modules=[
["dashboard","Dashboard","⌂","Vista ejecutiva del proyecto, actividad reciente y situación general de la red vial."],
["proyectos","Proyectos","▦","Administra proyectos territoriales con persistencia real en la base de datos."],
["mapa","Mapa y GPS","▧","Explora la red vial, ubica activos y revisa incidencias sobre el territorio."],
["caminos","Caminos y tramos","⌁","Administra caminos, segmentos, progresivas y atributos de la red."],
["kilometraje","Kilometraje y progresiva","↗","Control técnico de kilometraje, progresivas y referencias de terreno."],
["inspecciones","Inspecciones","☑","Programa y documenta inspecciones con hallazgos y evidencia."],
["inventario","Inventario vial","▤","Catastro de infraestructura, activos y equipamiento vial."],
["incidencias","Incidencias","△","Registra, clasifica y deriva eventos que afectan la condición vial."],
["mantenimiento","Mantenimiento","⚒","Planifica intervenciones, recursos, prioridades y ejecución."],
["formularios","Formularios y fichas","▧","Gestiona formularios técnicos y fichas configurables de terreno."],
["operaciones","Operaciones y permisos","♢","Control operativo, asignaciones y permisos por proyecto."],
["offline","Trabajo sin conexión","☁","Administra registros locales, mapas descargados y sincronización."],
["informes","Informes y exportaciones","▥","Construye informes, analiza resultados y prepara exportaciones."],
["configuracion","Configuración y auditoría","⚙","Parámetros del proyecto, fuentes cartográficas, capas y trazabilidad."],
["usuarios","Usuarios","♙","Administra usuarios, organizaciones, roles e invitaciones."],
["administracion","Administración","▦","Gestiona suscripciones, planes, licencias y parámetros de plataforma."]
];
const initial=[
{code:"INS-2026-028",name:"Inspección de pavimento",type:"Inspección",road:"R-720",km:"12+300",date:"20 oct 2026",status:"Completada",tone:"success",owner:"Juan Pérez"},
{code:"INC-2026-067",name:"Desprendimiento de talud",type:"Incidencia",road:"R-720",km:"13+800",date:"20 oct 2026",status:"Crítica",tone:"danger",owner:"María González"},
{code:"INF-2026-012",name:"Alcantarilla tipo cajón",type:"Infraestructura",road:"R-720",km:"14+200",date:"19 oct 2026",status:"Operativa",tone:"success",owner:"Carlos Ruiz"},
{code:"MAN-2026-015",name:"Bacheo en calzada",type:"Intervención",road:"R-720",km:"15+600",date:"19 oct 2026",status:"Ejecutada",tone:"info",owner:"Ana Torres"},
{code:"OPE-2026-009",name:"Cierre parcial por obras",type:"Operación",road:"R-720",km:"16+400",date:"18 oct 2026",status:"Programada",tone:"warning",owner:"Luis Soto"},
{code:"INS-2026-025",name:"Inspección de señalética",type:"Inspección",road:"R-720",km:"11+950",date:"18 oct 2026",status:"Pendiente",tone:"warning",owner:"Juan Pérez"},
{code:"INC-2026-061",name:"Señal dañada",type:"Incidencia",road:"R-720",km:"10+200",date:"17 oct 2026",status:"En revisión",tone:"info",owner:"Carlos Ruiz"},
{code:"MAN-2026-011",name:"Limpieza de faja",type:"Intervención",road:"R-720",km:"9+700",date:"16 oct 2026",status:"Programada",tone:"warning",owner:"Ana Torres"}];
const initialUsers=[
{name:"Juan Pérez",email:"juan.perez@ejemplo.cl",role:"Administrador",org:"Municipalidad",state:"Activo",last:"20 oct 2026 14:32"},
{name:"María González",email:"maria.gonzalez@ejemplo.cl",role:"Supervisora",org:"Municipalidad",state:"Activo",last:"20 oct 2026 12:18"},
{name:"Carlos Ruiz",email:"carlos.ruiz@ejemplo.cl",role:"Inspector",org:"Contratista",state:"Activo",last:"20 oct 2026 11:45"},
{name:"Ana Torres",email:"ana.torres@ejemplo.cl",role:"Consultora",org:"Consultora",state:"Activo",last:"19 oct 2026 16:20"},
{name:"Luis Soto",email:"luis.soto@ejemplo.cl",role:"Visualización",org:"Municipalidad",state:"Inactivo",last:"15 oct 2026 09:12"}];
const load=(k,v)=>{try{return JSON.parse(localStorage.getItem(k))||structuredClone(v)}catch{return structuredClone(v)}};
let records=load("geo.records",initial), users=load("geo.users",initialUsers), active="dashboard", query="", typeFilter="", selectedCode=null, seq=70, tab="Resumen";
let geoOrg=null, geoProjects=[], geoProjectsLoading=false, geoProjectsError="", geoCurrentUser=null;
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const mod=id=>modules.find(m=>m[0]===id)||modules[0];
const save=()=>{try{localStorage.setItem("geo.records",JSON.stringify(records));localStorage.setItem("geo.users",JSON.stringify(users))}catch{}};
const btn=(text,action,cls="",extra="")=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(s,t)=>`<span class="badge ${t}">${esc(s)}</span>`;
const kpi=(n,l,s,ico,t="")=>`<article class="kpi"><span class="kpi-icon ${t}">${ico}</span><div><strong>${n}</strong><label>${l}</label><small>${s}</small></div></article>`;
const head=(title,desc,actions="")=>`<div class="heading"><div><div class="eyebrow">GEOTRACIA / ${esc(mod(active)[1])}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const panel=(title,body,subtitle="",action="")=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<div class="sub">${subtitle}</div>`:""}</div>${action}</div>${body}</section>`;
const body=html=>`<div class="panel-body">${html}</div>`;
const activity=(ico,title,desc,time,tone="")=>`<div class="activity"><span class="activity-icon ${tone}">${ico}</span><div><b>${title}</b><p>${desc}</p><small>${time}</small></div></div>`;
const quick=(ico,title,desc,act)=>`<button class="quick" data-action="${act}"><i>${ico}</i><span><b>${title}</b><small>${desc}</small></span></button>`;
const map=()=>`<div class="panel-body"><div class="map"><div class="road"></div><span class="pin p1">✓</span><span class="pin p2">!</span><span class="pin p3">!</span><span class="map-label" style="left:35%;top:48%">Km 12.4</span><span class="map-label" style="left:57%;top:31%">Km 13.8</span><div class="map-tools"><button data-action="layers">▤</button><button data-action="center">⌖</button><button data-action="zoom">+</button></div><div class="legend"><span>Infraestructura</span><span>En revisión</span><span>Incidencia crítica</span></div></div><div class="sub" style="margin-top:9px">Vista territorial esquemática · No representa cartografía georreferenciada.</div></div>`;
function mapPanel(){return panel("Mapa de la red vial",map(),"Capas operativas y referencias de progresiva",btn("Capas","layers"))}
function bars(){let a=[38,28,18,16,9,6],l=["Inspec.","Incid.","Infra.","Interv.","Oper.","Otros"];return panel("Registros por categoría",body(`<div class="bars">${a.map((v,i)=>`<div class="barcol"><b>${v}</b><div class="bar ${i===2||i===3?"green":""}" style="height:${v/40*100}%"></div><small>${l[i]}</small></div>`).join("")}</div><div class="sub" style="margin-top:10px">Distribución demostrativa de registros</div>`),"Resumen de actividad del proyecto")}
function match(r,q){return !q||Object.values(r).some(v=>String(v).toLowerCase().includes(q.toLowerCase()))}
function table(data=records,limit=100){let d=data.slice(0,limit);return `<div class="table-scroll"><table><thead><tr><th>REGISTRO</th><th>TIPO</th><th>CAMINO / KM</th><th>RESPONSABLE</th><th>ESTADO</th><th></th></tr></thead><tbody>${d.map(r=>`<tr><td><span class="cell-title">${esc(r.code)}</span><div class="cell-sub">${esc(r.name)}</div></td><td>${esc(r.type)}</td><td><b>${esc(r.road)}</b><div class="cell-sub">Km ${esc(r.km)}</div></td><td>${esc(r.owner)}</td><td>${badge(r.status,r.tone)}</td><td><div class="row-actions"><button data-view="${esc(r.code)}" title="Ver">◉</button><button data-edit="${esc(r.code)}" title="Editar">✎</button><button data-delete="${esc(r.code)}" title="Eliminar">···</button></div></td></tr>`).join("")||`<tr><td colspan="6"><div class="empty">No hay registros para los filtros seleccionados.</div></td></tr>`}</tbody></table></div>`}
function tableTools(){return `<div class="table-tools"><label class="field-search">⌕ <input id="tableSearch" placeholder="Buscar código, descripción, responsable…" value="${esc(query)}"></label><select class="field" id="typeFilter" style="max-width:160px"><option value="">Todos los tipos</option>${["Inspección","Incidencia","Infraestructura","Intervención","Operación"].map(x=>`<option ${typeFilter===x?"selected":""}>${x}</option>`).join("")}</select><button class="btn" data-action="clear-filters">Limpiar filtros</button></div>`}
function recordPanel(){let d=records.filter(r=>match(r,query)&&(!typeFilter||r.type===typeFilter));return panel("Registros del módulo",`${tableTools()}<div id="recordsTable">${table(d)}</div><div class="pagination"><span>${d.length} registros visibles · almacenamiento local</span><div class="pages"><button>‹</button><button class="selected">1</button><button>›</button></div></div>`,"Consulta, filtra y abre los registros para revisar sus datos.",btn("＋ Nuevo registro","new-record","primary"))}
function dash(){return `${head("Control territorial","Una visión clara del estado de la red, las actividades de terreno y los asuntos que requieren atención.",btn("↓ Exportar resumen","export-csv")+btn("＋ Nuevo registro","new-record","primary"))}<div class="kpis">${kpi("156","Registros incluidos","En el proyecto","▤")}${kpi("42,6 km","Red analizada","Tramos seleccionados","⌁","teal")}${kpi("28","Incidencias","4 requieren atención","△","amber")}${kpi("16","Intervenciones","Mantenimiento","⚒","purple")}${kpi("94,2%","Cobertura de inspección","Periodo actual","✓","teal")}${kpi("3","Pendientes críticos","Revisión requerida","!","red")}</div><div class="grid2">${mapPanel()}${panel("Actividad reciente",body(`<div>${activity("☑","Inspección de pavimento","INS-2026-028 · Ruta R-720, km 12+300","Hoy · 14:32","teal")}${activity("△","Desprendimiento de talud","INC-2026-067 · Requiere evaluación","Hoy · 12:18","red")}${activity("▤","Activo vial actualizado","INF-2026-012 · Alcantarilla","Ayer · 16:20")}${activity("⚒","Mantenimiento programado","MAN-2026-015 · Bacheo","Ayer · 11:45","amber")}</div>${btn("Ver toda la actividad","go-reports")}`),"Últimos movimientos del proyecto")}</div><div class="grid3">${bars()}${recordPanel()}${panel("Acciones frecuentes",body(`<div class="quick-grid">${quick("＋","Crear registro","Formulario técnico","new-record")}${quick("△","Reportar incidencia","Evento en terreno","new-incident")}${quick("▥","Generar informe","Resumen de la red","go-reports")}${quick("♙","Gestionar usuarios","Accesos del equipo","go-users")}${quick("☁","Preparar offline","Mapas y registros","go-offline")}${quick("⚙","Configuración","Preferencias del proyecto","go-config")}</div>`))}</div>`}
function recordsModule(){let d=records.filter(r=>match(r,query));if(active==="inspecciones")d=d.filter(r=>r.type==="Inspección");if(active==="incidencias")d=d.filter(r=>r.type==="Incidencia");if(active==="mantenimiento")d=d.filter(r=>r.type==="Intervención");if(active==="inventario")d=d.filter(r=>r.type==="Infraestructura");if(active==="operaciones")d=d.filter(r=>r.type==="Operación");return `${head(mod(active)[1],mod(active)[3],btn("↓ Exportar","export-csv")+btn("＋ Nuevo registro",active==="incidencias"?"new-incident":"new-record","primary"))}<div class="kpis">${kpi(d.length,"Registros visibles","Según filtros","▤")}${kpi(d.filter(r=>r.tone==="danger").length,"Prioridad crítica","Revisión requerida","△","red")}${kpi(d.filter(r=>r.tone==="warning").length,"Pendientes","En seguimiento","◷","amber")}${kpi("R-720","Camino activo","Proyecto seleccionado","⌁","teal")}${kpi("42,6 km","Extensión","Red de referencia","↗","purple")}${kpi("20 oct","Última actividad","Fecha de ejemplo","▦")}</div>${recordPanel()}<div class="module-layout" style="margin-top:15px"><div>${mapPanel()}</div><div>${panel("Seguimiento",body(`<div class="progress-row"><span>Completados</span><b>68%</b></div><div class="progress"><span style="width:68%"></span></div><div class="settings-row"><span class="setting-icon">✓</span><span class="setting-copy"><b>Completados</b><small>Actividades cerradas o verificadas</small></span></div><div class="settings-row"><span class="setting-icon">◷</span><span class="setting-copy"><b>Pendientes de revisión</b><small>Requieren acción del equipo</small></span></div>`))}</div></div>`}
function settingsRow(ico,title,desc,status=""){return `<div class="settings-row"><span class="setting-icon">${ico}</span><span class="setting-copy"><b>${title}</b><small>${desc}</small></span>${status?badge(status,status==="Activo"?"success":"warning"):""}</div>`}
function projectModule(){
 const client=window.geoSupabase;
 if(!client) return `${head("Proyectos","Administra proyectos territoriales de tu organización.")}<div class="note">Inicia sesión para consultar proyectos.</div>`;
 if(geoProjectsLoading) return `${head("Proyectos","Proyectos asociados a tu organización.")}<section class="panel"><div class="panel-body">Consultando proyectos en Supabase…</div></section>`;
 if(geoProjectsError) return `${head("Proyectos","Proyectos asociados a tu organización.",btn("↻ Reintentar","reload-projects","primary"))}<div class="note">${esc(geoProjectsError)}</div>`;
 if(!geoOrg) return `${head("Configurar espacio de trabajo","Antes de crear proyectos, registra la organización que será propietaria de sus datos.")}<section class="panel"><div class="panel-head"><div><h2>Crear organización</h2><div class="sub">Cada organización tendrá sus propios proyectos y datos aislados.</div></div></div><div class="panel-body"><form id="orgCreateForm" class="form-grid"><div class="full"><label class="field-label" for="orgCreateName">Nombre de la organización</label><input class="field" id="orgCreateName" required minlength="2" maxlength="160" placeholder="Ej. Consultora Vial Sur"></div><div class="full"><button class="btn primary" type="submit">Crear espacio de trabajo</button></div></form></div></section>`;
 const rows=geoProjects.map(p=>`<tr><td><span class="cell-title">${esc(p.code||"—")}</span><div class="cell-sub">${esc(p.description||"Sin descripción")}</div></td><td><b>${esc(p.name)}</b></td><td>${esc(p.region||"Sin región")}</td><td>${badge(projectStatus(p.status),p.status==="closed"||p.status==="archived"?"warning":"success")}</td><td>${new Date(p.created_at).toLocaleDateString("es-CL")}</td><td><div class="row-actions"><button type="button" data-project-edit="${esc(p.id)}" title="Editar">✎</button><button type="button" data-project-delete="${esc(p.id)}" title="Archivar">▣</button></div></td></tr>`).join("");
 return `${head("Proyectos",`Espacio de trabajo: <b>${esc(geoOrg.name)}</b>. Los proyectos se guardan en PostgreSQL.`,btn("↻ Actualizar","reload-projects")+btn("＋ Nuevo proyecto","new-project","primary"))}<div class="kpis">${kpi(geoProjects.length,"Proyectos","Registros de tu organización","▦")}${kpi(geoProjects.filter(p=>p.status==="open").length,"Activos","Estado abierto","✓","teal")}${kpi(geoProjects.filter(p=>p.status==="in_progress").length,"En ejecución","Trabajo en curso","↻","amber")}${kpi(geoProjects.filter(p=>["closed","archived"].includes(p.status)).length,"Cerrados / archivados","Histórico","▤","purple")}</div><section class="panel"><div class="panel-head"><div><h2>Directorio de proyectos</h2><div class="sub">Datos reales de Supabase · ${geoProjects.length} proyectos</div></div></div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>CÓDIGO / DESCRIPCIÓN</th><th>PROYECTO</th><th>REGIÓN</th><th>ESTADO</th><th>CREADO</th><th>ACCIONES</th></tr></thead><tbody>${rows||'<tr><td colspan="6"><div class="empty">Todavía no hay proyectos. Crea el primero para comenzar.</div></td></tr>'}</tbody></table></div></div></section><div class="note" style="margin-top:12px">La autorización se valida también en Supabase mediante RLS; ocultar acciones en la interfaz no sustituye los permisos del servidor.</div>`;
}
function projectStatus(s){return ({draft:"Borrador",open:"Activo",in_progress:"En ejecución",resolved:"Resuelto",closed:"Cerrado",archived:"Archivado"})[s]||s||"Activo"}
async function loadGeoProjects(){const client=window.geoSupabase;if(!client)return;geoProjectsLoading=true;geoProjectsError="";if(active==="proyectos")show();try{const {data:userData,error:userError}=await client.auth.getUser();if(userError)throw userError;geoCurrentUser=userData.user;if(!geoCurrentUser)throw new Error("La sesión no está activa. Inicia sesión nuevamente.");const {data:members,error:mErr}=await client.from("members").select("organization_id, role, organizations(id,name)").eq("user_id",geoCurrentUser.id).eq("active",true).limit(1);if(mErr)throw mErr;const membership=members?.[0];if(!membership){geoOrg=null;geoProjects=[];return;}geoOrg={id:membership.organization_id,name:membership.organizations?.name||"Organización",role:membership.role};const {data,error}=await client.from("projects").select("id,organization_id,name,code,description,region,status,created_at,updated_at").eq("organization_id",geoOrg.id).order("created_at",{ascending:false});if(error)throw error;geoProjects=data||[];}catch(e){geoProjectsError=projectErrorMessage(e);geoProjects=[];}finally{geoProjectsLoading=false;if(active==="proyectos")show();}}
function projectErrorMessage(e){const m=e?.message||"No fue posible consultar los proyectos.";if(/relation .* does not exist|schema cache/i.test(m))return "No se encuentran las tablas necesarias. Ejecuta las migraciones SQL de GEOTRACIA en Supabase.";if(/permission denied|row-level security|violates row-level/i.test(m))return "Supabase rechazó la operación por permisos o políticas RLS. Revisa la migración y la pertenencia a la organización.";return m}
function newProject(p=null){dialog(p?"Editar proyecto":"Nuevo proyecto",`<form id="projectForm" class="form-grid"><div><label class="field-label" for="pName">Nombre del proyecto *</label><input class="field" id="pName" required maxlength="160" value="${esc(p?.name||"")}" placeholder="Ej. Conservación Ruta R-720"></div><div><label class="field-label" for="pCode">Código</label><input class="field" id="pCode" maxlength="60" value="${esc(p?.code||"")}" placeholder="Ej. R720-2026"></div><div><label class="field-label" for="pRegion">Región</label><input class="field" id="pRegion" maxlength="120" value="${esc(p?.region||"")}" placeholder="La Araucanía"></div><div><label class="field-label" for="pStatus">Estado</label><select class="field" id="pStatus">${[["draft","Borrador"],["open","Activo"],["in_progress","En ejecución"],["closed","Cerrado"],["archived","Archivado"]].map(([v,l])=>`<option value="${v}" ${p?.status===v?"selected":(!p&&v==="open"?"selected":"")}>${l}</option>`).join("")}</select></div><div class="full"><label class="field-label" for="pDescription">Descripción</label><textarea class="field" id="pDescription" rows="3" maxlength="4000" placeholder="Alcance, objetivos y notas">${esc(p?.description||"")}</textarea></div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="save-project" data-project-id="${esc(p?.id||"")}">Guardar proyecto</button>`)}
async function saveGeoProject(id=""){const form=$("#projectForm");if(!form?.reportValidity())return;if(!geoOrg)return toast("Primero crea o selecciona una organización.");const client=window.geoSupabase;const payload={organization_id:geoOrg.id,name:$("#pName").value.trim(),code:$("#pCode").value.trim()||null,region:$("#pRegion").value.trim()||null,description:$("#pDescription").value.trim(),status:$("#pStatus").value,created_by:geoCurrentUser?.id};const button=$("[data-action=save-project]");if(button){button.disabled=true;button.textContent="Guardando…"}try{let result;if(id){delete payload.created_by;result=await client.from("projects").update({...payload,updated_at:new Date().toISOString()}).eq("id",id).eq("organization_id",geoOrg.id).select("id").single()}else result=await client.from("projects").insert(payload).select("id").single();if(result.error)throw result.error;try{await client.from("audit_logs").insert({organization_id:geoOrg.id,actor_id:geoCurrentUser?.id,action:id?"project.updated":"project.created",entity_table:"projects",entity_id:result.data.id,details:{name:payload.name,code:payload.code}})}catch{}$("#dialog").close();toast(id?"Proyecto actualizado en Supabase":"Proyecto creado en Supabase");await loadGeoProjects()}catch(e){toast(projectErrorMessage(e))}finally{if(button){button.disabled=false;button.textContent="Guardar proyecto"}}}
async function createGeoOrganization(name){const client=window.geoSupabase;try{const {data,error}=await client.rpc("create_my_organization",{org_name:name.trim()});if(error)throw error;toast("Organización creada");await loadGeoProjects()}catch(e){toast(projectErrorMessage(e))}}
async function archiveGeoProject(id){const p=geoProjects.find(x=>x.id===id);if(!p)return;dialog("Archivar proyecto",`<p>¿Archivar <b>${esc(p.name)}</b>? El proyecto y sus registros no se eliminarán.</p>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="archive-project-confirm" data-project-id="${esc(id)}">Archivar</button>`)}
async function confirmArchiveProject(id){try{const {error}=await window.geoSupabase.from("projects").update({status:"archived",updated_at:new Date().toISOString()}).eq("id",id).eq("organization_id",geoOrg.id);if(error)throw error;try{await window.geoSupabase.from("audit_logs").insert({organization_id:geoOrg.id,actor_id:geoCurrentUser?.id,action:"project.archived",entity_table:"projects",entity_id:id,details:{name:geoProjects.find(p=>p.id===id)?.name}})}catch{}$("#dialog").close();toast("Proyecto archivado");await loadGeoProjects()}catch(e){toast(projectErrorMessage(e))}}
function generic(){return `${head(mod(active)[1],mod(active)[3],btn("↓ Exportar","export-csv")+btn("＋ Crear nuevo","new-record","primary"))}<div class="kpis">${kpi("42,6 km","Red de referencia","Proyecto activo","⌁")}${kpi("156","Registros","Datos demostrativos","▤","teal")}${kpi("12","Pendientes","Seguimiento","◷","amber")}${kpi("94%","Completitud","Indicador ilustrativo","✓","purple")}</div><div class="module-layout"><div class="stack">${panel(active==="caminos"?"Red vial del proyecto":mod(active)[1],`<div class="tabs">${["Resumen","Registros","Configuración"].map(x=>`<button class="tab ${tab===x?"active":""}" data-tab="${x}">${x}</button>`).join("")}</div><div id="tabBody" class="panel-body">${tabContent(tab)}</div>`,"Componentes listos para conectar con servicios y reglas reales.")}${recordPanel()}</div><div class="stack">${mapPanel()}${panel("Acciones del módulo",body(`<div class="quick-grid">${quick("＋","Crear registro","Nuevo elemento","new-record")}${quick("▥","Crear informe","Resumen de actividad","go-reports")}${quick("↓","Exportar","Datos de demostración","export-csv")}${quick("⚙","Preferencias","Opciones del módulo","settings")}</div>`))}</div></div>`}
function tabContent(t){if(t==="Configuración")return `<div>${settingsRow("⚙","Campos del módulo","Configuración visual")}${settingsRow("♧","Notificaciones","Avisos de actividad")}${settingsRow("♢","Validaciones","Pendiente de conectar")}</div>`;if(t==="Registros")return table(records.slice(0,4),4);return `<div class="report-stats">${[["24","Elementos","▤"],["12","Pendientes","◷"],["94%","Completitud","✓"],["3","Alertas","△"]].map(r=>`<div class="result"><span>${r[2]}</span><strong>${r[0]}</strong><small>${r[1]}</small></div>`).join("")}</div><p class="sub" style="margin-top:14px">Estructura visual de referencia. Los procesos de dominio se conectarán al implementar el backend.</p>`}
function roads(){return `${head("Caminos y tramos",mod("caminos")[3],btn("↑ Importar datos","import-road")+btn("＋ Nuevo camino","new-road","primary"))}<div class="kpis">${kpi("24","Caminos","En el proyecto","⌁")}${kpi("186","Tramos","Segmentos registrados","⌁","teal")}${kpi("42,6 km","Longitud total","Red seleccionada","↗","purple")}${kpi("96%","Datos completos","Atributos esenciales","✓","teal")}</div><div class="module-layout"><div>${panel("Red vial del proyecto",`<div class="table-tools"><label class="field-search">⌕ <input id="roadSearch" placeholder="Buscar camino o tramo…"></label></div><div class="table-scroll"><table><thead><tr><th>CÓDIGO</th><th>NOMBRE DEL CAMINO</th><th>INICIO</th><th>TÉRMINO</th><th>LONGITUD</th><th>ESTADO</th><th></th></tr></thead><tbody id="roadRows">${[["R-720","Ruta R-720","0+000","42+600","42,6 km","Activo","success"],["R-51","Ruta S-51","0+000","18+200","18,2 km","Activo","success"],["TR-018","Acceso sector Labranza","0+000","4+800","4,8 km","En revisión","warning"],["TR-024","Conexión Padre Las Casas","0+000","7+100","7,1 km","Activo","success"],["TR-031","Camino rural norte","0+000","11+500","11,5 km","Programado","info"]].map(r=>`<tr><td>${r[0]}</td><td><b>${r[1]}</b><div class="cell-sub">Red vial regional</div></td><td>Km ${r[2]}</td><td>Km ${r[3]}</td><td>${r[4]}</td><td>${badge(r[5],r[6])}</td><td><button class="icon" data-action="road-detail">◉</button></td></tr>`).join("")}</tbody></table></div>`,"Gestión de caminos y segmentos")}</div><div class="stack">${panel("Resumen de red",body(kpi("42,6 km","Longitud inventariada","Suma de tramos","⌁","teal")+`<div class="progress-row"><span>Catastro completado</span><b>82%</b></div><div class="progress"><span style="width:82%"></span></div>`))}${mapPanel()}</div></div>`}
function offline(){return `${head("Trabajo sin conexión",mod(active)[3],btn("⚙ Configuración","offline-settings")+btn("☁ Sincronizar ahora","sync","primary"))}<div class="kpis">${kpi("12","En espera","Registros locales","☁","amber")}${kpi("248","Sincronizados","Última sincronización","✓","teal")}${kpi("3","Con conflictos","Necesitan revisión","△","red")}${kpi("62%","Almacenamiento","3,1 GB de 5 GB","▤","purple")}</div><div class="module-layout"><div class="stack">${panel("Estado de sincronización",body(`<div class="progress-row"><span>Cola de sincronización</span><b>9 de 12 registros</b></div><div class="progress"><span style="width:75%"></span></div><div class="settings-row">${settingsRow("✓","Registros sincronizados","248 registros de referencia","Activo")}</div>${settingsRow("↻","En proceso","2 elementos en cola")}${settingsRow("◷","En espera","1 elemento pendiente")}${settingsRow("△","Conflictos","3 registros requieren revisión","Pendiente")}<div style="margin-top:12px">${btn("Resolver conflictos","conflicts")}</div>`),"El modo offline aún no sincroniza con servidor.")}${recordPanel()}</div><div class="stack">${panel("Mapas offline",body(["Ruta R-720 · 320 MB","Padre Las Casas · 185 MB","Sector Labranza · 120 MB","Ruta S-51 · 210 MB"].map((x,i)=>settingsRow("▧",x,i===2?"Pendiente de descarga":"Última actualización de ejemplo",i===2?"Pendiente":"Activo")).join("")+btn("Descargar mapa","download-map")))}${panel("Almacenamiento",body(`<div class="progress-row"><span>Espacio utilizado</span><b>3,1 GB / 5 GB</b></div><div class="progress"><span style="width:62%"></span></div><p class="sub">Mapas offline 2,1 GB · Archivos 650 MB · Registros 280 MB</p>${btn("Limpiar datos locales","clear-local","danger-btn")}`))}</div></div>`}
function reports(){return `${head("Informes y exportaciones",mod(active)[3],btn("Plantillas","templates")+btn("＋ Nuevo informe","new-report","primary"))}<div class="kpis">${kpi("156","Registros incluidos","Filtros actuales","▤")}${kpi("42,6 km","Tramos analizados","Red vial","⌁","teal")}${kpi("28","Incidencias","En el periodo","△","amber")}${kpi("16","Intervenciones","Mantenimiento","⚒","purple")}</div>${panel("Filtros del informe",`<div class="panel-body"><div class="form-grid"><div><label class="field-label">Tipo de informe</label><select class="field"><option>Estado de la red vial</option><option>Incidencias críticas</option><option>Avance de mantenimiento</option></select></div><div><label class="field-label">Periodo</label><input class="field" value="01 oct 2026 - 31 oct 2026"></div><div><label class="field-label">Camino</label><select class="field"><option>R-720</option><option>Todos</option></select></div><div><label class="field-label">Estado</label><select class="field"><option>Todos</option><option>Completada</option></select></div></div><div class="actions" style="margin-top:13px">${btn("Limpiar filtros","clear-report")}${btn("⌕ Generar informe","generate-report","primary")}</div></div>`)}<div style="height:14px"></div><div class="module-layout"><div class="stack">${panel("Resumen de resultados",body(`<div class="report-stats">${[["42,6 km","Longitud analizada","⌁"],["68","Elementos de infraestructura","▤"],["28","Incidencias registradas","△"],["16","Intervenciones","⚒"]].map(r=>`<div class="result"><span>${r[2]}</span><strong>${r[0]}</strong><small>${r[1]}</small></div>`).join("")}</div>`))}${bars()}${recordPanel()}</div><div class="stack">${mapPanel()}${panel("Exportar informe",body(`<div class="quick-grid">${quick("PDF","PDF","Pendiente motor PDF","export-pdf")}${quick("XLS","Excel","Hoja de cálculo","export-csv")}${quick("CSV","CSV","Datos tabulares","export-csv")}${quick("KML","KML","Pendiente GIS","export-kml")}</div><div style="margin-top:12px">${btn("↓ Exportar CSV","export-csv","primary")}</div>`))}${panel("Informes programados",body(settingsRow("▦","Reporte mensual de estado","Cada mes · día 1","Activo")+settingsRow("△","Incidencias críticas","Cada semana · lunes","Activo")+settingsRow("⚒","Avance de mantenimiento","Cada 15 días","Pendiente")))}</div></div>`}
function usersModule(){return `${head("Usuarios",mod(active)[3],btn("↓ Exportar usuarios","export-users")+btn("＋ Nuevo usuario","new-user","primary"))}<div class="kpis">${kpi(users.length,"Usuarios registrados","Datos locales","♙")}${kpi(users.filter(u=>u.state==="Activo").length,"Usuarios activos","Cuentas habilitadas","✓","teal")}${kpi(users.filter(u=>u.state!=="Activo").length,"Usuarios inactivos","Cuentas deshabilitadas","×","red")}${kpi("6","Roles definidos","Modelo referencial","♢","purple")}${kpi("3","Organizaciones","Agrupación ejemplo","▦","amber")}${kpi("2","Invitaciones pendientes","Sin envío de correo","✉")}</div><div class="module-layout"><div>${panel("Directorio de usuarios",`<div class="table-tools"><label class="field-search">⌕ <input id="userSearch" placeholder="Buscar nombre o correo…" value="${esc(query)}"></label><select class="field" id="userState" style="max-width:140px"><option value="">Todos los estados</option><option>Activo</option><option>Inactivo</option></select></div><div id="userTable">${userTable()}</div><div class="pagination"><span>${users.length} usuarios en datos locales</span>${btn("＋ Nuevo usuario","new-user","primary")}</div>`,"Roles, organizaciones y estado de cuenta")}</div><div class="stack">${panel("Roles y permisos",body([["Administrador","Acceso administrativo completo","♢"],["Supervisor","Gestión y supervisión","✓"],["Inspector","Registro y edición de inspecciones","☑"],["Consultora","Consulta e informes","▥"],["Visualización","Solo lectura","◉"]].map(r=>settingsRow(r[2],r[0],r[1])).join("")))}${panel("Acciones rápidas",body(`<div class="quick-grid">${quick("＋","Nuevo usuario","Crear cuenta de demo","new-user")}${quick("♢","Gestionar roles","Revisar permisos","roles")}${quick("✉","Invitación","Simular invitación","invite")}${quick("▤","Auditoría","Eventos recientes","audit")}</div>`))}</div></div>`}
function userTable(){let d=users.filter(u=>!query||[u.name,u.email,u.role,u.org].join(" ").toLowerCase().includes(query.toLowerCase()));if($("#userState")?.value)d=d.filter(u=>u.state===$("#userState").value);return `<div class="table-scroll"><table><thead><tr><th>USUARIO</th><th>ROL</th><th>ORGANIZACIÓN</th><th>ESTADO</th><th>ÚLTIMO ACCESO</th><th></th></tr></thead><tbody>${d.map(u=>`<tr><td><b>${esc(u.name)}</b><div class="cell-sub">${esc(u.email)}</div></td><td>${esc(u.role)}</td><td>${esc(u.org)}</td><td>${badge(u.state,u.state==="Activo"?"success":"danger")}</td><td>${esc(u.last)}</td><td><div class="row-actions"><button data-user-edit="${esc(u.email)}">✎</button><button data-user-toggle="${esc(u.email)}">↻</button></div></td></tr>`).join("")||`<tr><td colspan="6">Sin coincidencias</td></tr>`}</tbody></table></div>`}
function config(){return `${head("Configuración y auditoría",mod(active)[3],btn("↓ Exportar auditoría","audit")+btn("Guardar cambios","save-config","primary"))}<div class="kpis">${kpi("24","Parámetros del sistema","Configuración general","⚙")}${kpi("5","Fuentes cartográficas","Activas / disponibles","▤","teal")}${kpi(users.length,"Usuarios","En esta demo","♙","amber")}${kpi("12.548","Eventos de auditoría","Dato referencial","▧","purple")}${kpi("3,1 GB","Almacenamiento","Mapas y archivos","▤")}${kpi("2","Actualizaciones","Pendientes","↻","amber")}</div><div class="module-layout"><div class="stack">${panel("Configuración general",body(`<div class="form-grid"><div><label class="field-label">Nombre del proyecto</label><input class="field" id="projectName" value="Ruta R-720 - Conservación 2024"></div><div><label class="field-label">Región</label><select class="field"><option>La Araucanía</option><option>Los Ríos</option></select></div><div class="full"><label class="field-label">Descripción</label><textarea class="field" rows="3">Monitoreo y gestión de la red vial regional.</textarea></div><div><label class="field-label">Zona horaria</label><select class="field"><option>(GMT-03:00) Santiago</option></select></div><div><label class="field-label">Sistema de coordenadas</label><select class="field"><option>WGS 84 (EPSG:4326)</option><option>UTM 18S</option></select></div><div><label class="field-label">Unidades de distancia</label><select class="field"><option>Kilómetros (km)</option><option>Metros (m)</option></select></div><div><label class="field-label">Formato de fecha</label><select class="field"><option>dd/mm/aaaa</option><option>aaaa-mm-dd</option></select></div></div>`))}${panel("Fuentes cartográficas",body(settingsRow("▤","OpenStreetMap","Fuente base; no conectada","Activo")+settingsRow("▧","IDE Chile (MOP)","Requiere configuración","Pendiente")+settingsRow("◈","ESRI World Imagery","Proveedor/licencia no conectada","Pendiente")+btn("＋ Configurar fuente","add-source")))}</div><div class="stack">${mapPanel()}${panel("Preferencias del entorno",body(settingsRow("☁","Sincronización automática","Backend pendiente","Pendiente")+settingsRow("♧","Notificaciones","Avisos en interfaz","Activo")+settingsRow("♢","Confirmar acciones destructivas","Confirmación de seguridad","Activo")+settingsRow("▤","Guardar preferencias locales","Este navegador","Activo")))}${panel("Mantenimiento",body(quick("↓","Exportar datos locales","Descargar respaldo JSON","backup")+quick("↻","Restaurar demo","Datos iniciales","reset")))}</div></div>`}
function admin(){return `${head("Administración",mod(active)[3],btn("⚙ Parámetros","go-config")+btn("＋ Nueva suscripción","new-subscription","primary"))}<div class="kpis">${kpi(users.length,"Usuarios activos","Datos de muestra","♙")}${kpi("3","Organizaciones","Clientes de referencia","▦","teal")}${kpi("3","Suscripciones","Datos ilustrativos","▤","purple")}${kpi("312 días","Vigencia promedio","Dato de ejemplo","▦","amber")}${kpi("$299.990","Ingreso mensual","CLP · simulación","$","teal")}${kpi("87%","Uso de plataforma","Métrica ilustrativa","◔")}</div><div class="module-layout"><div class="stack">${panel("Suscripciones y clientes",`<div class="table-scroll"><table><thead><tr><th>ORGANIZACIÓN</th><th>SUSCRIPCIÓN</th><th>PLAN</th><th>ESTADO</th><th>VIGENCIA</th><th></th></tr></thead><tbody>${[["Municipalidad de Ejemplo","SUB-00124","Empresa","Activa","20 oct 2027"],["Constructora Andina","SUB-00119","Profesional","Activa","15 sep 2027"],["Consultora Vial Sur","SUB-00115","Básico","Por vencer","30 oct 2026"],["Dirección de Vialidad","SUB-00110","Empresa","Activa","20 mar 2028"],["Servicios Territoriales","SUB-00108","Profesional","Suspendida","10 oct 2026"]].map(r=>`<tr>${r.slice(0,5).map((v,i)=>`<td>${i===3?badge(v,v==="Activa"?"success":"warning"):esc(v)}</td>`).join("")}<td><button class="icon" data-action="subscription-detail">◉</button></td></tr>`).join("")}</tbody></table></div><div class="pagination"><span>Suscripciones de muestra</span>${btn("＋ Nueva suscripción","new-subscription","primary")}</div>`,"Planes y vigencia · datos ilustrativos")}${panel("Ingresos y facturación",body(`<div class="bars">${[48,61,75,69,86,95].map((v,i)=>`<div class="barcol"><b>${[".5",".7",".9",".8","1.0","1.1"][i]}M</b><div class="bar green" style="height:${v}%"></div><small>${["May","Jun","Jul","Ago","Sep","Oct"][i]}</small></div>`).join("")}</div><p class="sub">Serie ilustrativa; no corresponde a pagos reales.</p>`))}</div><div class="stack">${panel("Planes y características",body(`<div class="stack">${plan("Básico","$149.990","Hasta 5 usuarios",["Mapa y GPS","Inspecciones","Informes básicos"])}${plan("Profesional","$299.990","Hasta 10 usuarios",["Módulos operativos","Trabajo offline","Informes avanzados"])}${plan("Empresa","$499.990","Hasta 50 usuarios",["Todos los módulos","Auditoría y reportes","Soporte prioritario"],true)}</div>`))}${panel("Acciones administrativas",body(`<div class="quick-grid">${quick("$","Registrar pago","Simulación","payment")}${quick("▤","Facturas","Vista de facturación","invoices")}${quick("◔","Uso y límites","Consumo del plan","usage")}${quick("↓","Respaldo","Exportar datos demo","backup")}</div>`))}</div></div>`}
function plan(n,p,l,features,featured=false){return `<div class="plan ${featured?"featured":""}"><h3>${n}</h3><div class="price">${p}<small style="font-size:9px;font-weight:500"> / mes</small></div><p>${l}</p><ul>${features.map(f=>`<li>✓ ${f}</li>`).join("")}</ul>${btn("Seleccionar plan","select-plan",featured?"primary":"")}</div>`}
function mapModule(){return `${head("Mapa y GPS",mod(active)[3],btn("▤ Capas","layers")+btn("⌖ Centrar mapa","center","primary"))}<div class="kpis">${kpi("42,6 km","Longitud analizada","Red seleccionada","⌁")}${kpi("68","Activos","Área de referencia","▤","teal")}${kpi("12","Inspecciones","Periodo actual","☑","purple")}${kpi("4","Alertas prioritarias","Revisión de terreno","△","red")}</div><div class="module-layout"><div class="stack">${mapPanel()}${recordPanel()}</div><div class="stack">${panel("Capas visibles",body(["Tramos de caminos","Incidencias","Intervenciones","Infraestructura","Inspecciones","Límite regional","Imágenes satelitales"].map((x,i)=>`<label class="settings-row"><input type="checkbox" ${i<5?"checked":""}> <span class="setting-copy"><b>${x}</b><small>Control de visibilidad</small></span></label>`).join("")))}${panel("Detalle territorial",body(settingsRow("⌁","Camino seleccionado","Ruta R-720 · La Araucanía")+settingsRow("↗","Progresiva","Km 12+400")+settingsRow("▦","Última revisión","20 oct 2026")))}</div></div>`}
function show(){let html=active==="dashboard"?dash():active==="proyectos"?projectModule():active==="mapa"?mapModule():active==="caminos"?roads():active==="offline"?offline():active==="informes"?reports():active==="usuarios"?usersModule():active==="configuracion"?config():active==="administracion"?admin():["inspecciones","inventario","incidencias","mantenimiento","operaciones"].includes(active)?recordsModule():generic();$("#content").innerHTML=html;renderNav();renderBottom();window.scrollTo({top:0,behavior:"smooth"});}
function renderNav(){$("#nav").innerHTML=modules.map(m=>`<button class="nav-item ${m[0]===active?"active":""}" data-go="${m[0]}"><span class="nav-icon">${m[2]}</span><span>${m[1]}</span>${m[0]==="inspecciones"?'<span class="nav-count">12</span>':m[0]==="incidencias"?'<span class="nav-count">3</span>':""}</button>`).join("")}
function renderBottom(){let old=$(".bottom-nav");if(old)old.remove();let n=document.createElement("nav");n.className="bottom-nav";let list=[modules[0],modules[1],modules[4],modules[11],modules[14]];n.innerHTML=list.map(m=>`<button class="${m[0]===active?"active":""}" data-go="${m[0]}"><span class="nav-icon">${m[2]}</span>${m[0]==="administracion"?"Más":m[1].split(" ")[0]}</button>`).join("");document.body.append(n)}
function go(id){active=id;query="";typeFilter="";$("#globalSearch").value="";$("#sidebar").classList.remove("open");$("#overlay").classList.remove("show");show();if(id==="proyectos")loadGeoProjects()}
function toast(msg){let t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>t.classList.remove("show"),3300)}
function dialog(title,body,foot=`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="confirm">Confirmar</button>`){$("#dialogTitle").textContent=title;$("#dialogBody").innerHTML=body;$("#dialogFoot").innerHTML=foot;$("#dialog").showModal()}
function field(label,id,placeholder="",value=""){return `<div><label class="field-label" for="${id}">${label}</label><input class="field" id="${id}" placeholder="${placeholder}" value="${esc(value)}"></div>`}
function recordForm(r={}){return `<form id="recordForm" class="form-grid"><div class="note full">Se guardará en este navegador para evaluar el prototipo. No se envía a un servidor.</div>${field("Código","rCode","Código",r.code||`REG-2026-${seq}`)}<div><label class="field-label">Tipo</label><select class="field" id="rType">${["Inspección","Incidencia","Infraestructura","Intervención","Operación"].map(x=>`<option ${r.type===x?"selected":""}>${x}</option>`).join("")}</select></div>${field("Nombre / descripción","rName","Describe el registro",r.name||"")}${field("Camino","rRoad","Ej. R-720",r.road||"R-720")}${field("Progresiva (km)","rKm","Ej. 12+300",r.km||"")}<div><label class="field-label">Estado</label><select class="field" id="rStatus">${["Pendiente","En revisión","Completada","Crítica","Programada","Operativa","Ejecutada"].map(x=>`<option ${r.status===x?"selected":""}>${x}</option>`).join("")}</select></div><div><label class="field-label">Responsable</label><select class="field" id="rOwner">${users.map(u=>`<option ${r.owner===u.name?"selected":""}>${esc(u.name)}</option>`).join("")}</select></div><div class="full"><label class="field-label">Observaciones</label><textarea class="field" id="rNotes" rows="3" placeholder="Contexto técnico o acciones recomendadas">${esc(r.notes||"")}</textarea></div></form>`}
function newRecord(type=""){selectedCode=null;dialog(type==="Incidencia"?"Reportar incidencia":"Nuevo registro técnico",recordForm({type}),`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="save-record">Guardar registro</button>`)}
function saveRecord(){if(!$("#recordForm").reportValidity())return;let s=$("#rStatus").value,tones={"Crítica":"danger","Pendiente":"warning","En revisión":"info","Programada":"warning","Completada":"success","Operativa":"success","Ejecutada":"info"};let r={code:$("#rCode").value.trim(),name:$("#rName").value.trim(),type:$("#rType").value,road:$("#rRoad").value.trim(),km:$("#rKm").value.trim(),date:new Date().toLocaleDateString("es-CL"),status:s,tone:tones[s]||"info",owner:$("#rOwner").value,notes:$("#rNotes").value};if(selectedCode)records=records.map(x=>x.code===selectedCode?r:x);else{records.unshift(r);seq++}save();$("#dialog").close();show();toast(selectedCode?"Registro actualizado localmente":"Registro creado localmente")}
function viewRecord(code){let r=records.find(x=>x.code===code);if(!r)return;dialog(r.name,`<div class="note">Ficha demostrativa · ${esc(r.code)}</div><div class="form-grid">${[["Código",r.code],["Tipo",r.type],["Camino",r.road],["Progresiva",r.km],["Estado",r.status],["Responsable",r.owner],["Fecha",r.date]].map(a=>`<div><label class="field-label">${a[0]}</label><div>${esc(a[1])}</div></div>`).join("")}<div class="full"><label class="field-label">Observaciones</label><p>${esc(r.notes||"Sin observaciones registradas.")}</p></div></div>`,`<button class="btn" data-close>Cerrar</button><button class="btn primary" data-action="edit-record" data-code="${esc(code)}">Editar registro</button>`)}
function editRecord(code){let r=records.find(x=>x.code===code);if(!r)return;selectedCode=code;dialog("Editar registro",recordForm(r),`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="save-record">Guardar cambios</button>`)}
function newUser(u=null){dialog(u?"Editar usuario":"Nuevo usuario",`<form id="userForm" class="form-grid">${field("Nombre completo","uName","Nombre y apellido",u?.name||"")}${field("Correo electrónico","uEmail","usuario@empresa.cl",u?.email||"")}<div><label class="field-label">Rol</label><select class="field" id="uRole">${["Administrador","Supervisora","Inspector","Consultora","Visualización"].map(x=>`<option ${u?.role===x?"selected":""}>${x}</option>`).join("")}</select></div><div><label class="field-label">Organización</label><select class="field" id="uOrg">${["Municipalidad","Contratista","Consultora","Dirección de Vialidad"].map(x=>`<option ${u?.org===x?"selected":""}>${x}</option>`).join("")}</select></div><label class="full"><input type="checkbox" id="uActive" ${u?.state!=="Inactivo"?"checked":""}> Cuenta activa</label><div class="note full">No se crea autenticación real ni se envía correo en esta versión.</div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="save-user" data-edit="${esc(u?.email||"")}">Guardar usuario</button>`)}
function saveUser(){if(!$("#userForm").reportValidity())return;let email=$("#uEmail").value.trim(),old=$("[data-action=save-user]").dataset.edit;let u={name:$("#uName").value.trim(),email,role:$("#uRole").value,org:$("#uOrg").value,state:$("#uActive").checked?"Activo":"Inactivo",last:"Sin acceso registrado"};if(old)users=users.map(x=>x.email===old?u:x);else if(users.some(x=>x.email.toLowerCase()===email.toLowerCase()))return toast("El correo ya existe");else users.unshift(u);save();$("#dialog").close();show();toast("Usuario guardado localmente")}
function userToggle(email){users=users.map(u=>u.email===email?{...u,state:u.state==="Activo"?"Inactivo":"Activo"}:u);save();show();toast("Estado de usuario actualizado")}
function exportFile(name,text,type){let a=document.createElement("a"),url=URL.createObjectURL(new Blob(["\\ufeff",text],{type}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportRecords(){exportFile("geotracia-registros.csv","Código,Nombre,Tipo,Camino,Progresiva,Fecha,Estado,Responsable\\n"+records.map(r=>[r.code,r.name,r.type,r.road,r.km,r.date,r.status,r.owner].map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(",")).join("\\n"),"text/csv;charset=utf-8");toast("CSV descargado")}
function act(a,e){switch(a){
case"new-record":newRecord();break;case"new-incident":newRecord("Incidencia");break;case"save-record":saveRecord();break;
case"new-project":newProject();break;case"save-project":saveGeoProject(e?.dataset?.projectId||"");break;case"reload-projects":loadGeoProjects();break;case"archive-project-confirm":confirmArchiveProject(e?.dataset?.projectId||"");break;
case"new-user":newUser();break;case"save-user":saveUser();break;
case"export-csv":exportRecords();break;case"export-users":exportFile("geotracia-usuarios.csv","Nombre,Correo,Rol,Organización,Estado\\n"+users.map(u=>[u.name,u.email,u.role,u.org,u.state].join(",")).join("\\n"),"text/csv");toast("Usuarios exportados");break;
case"new-road":dialog("Nuevo camino",`<form id="roadForm" class="form-grid">${field("Código","roadCode","Ej. R-720")}${field("Nombre del camino","roadName","Nombre oficial")}${field("Progresiva inicial","roadStart","Km 0+000")}${field("Progresiva final","roadEnd","Km 10+000")}<div class="note full">Formulario de evaluación; persistencia de caminos pendiente.</div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="save-road">Validar formulario</button>`);break;
case"save-road":if(!$("#roadForm").reportValidity())return;$("#dialog").close();toast("Formulario validado; guardado real pendiente");break;
case"go-reports":go("informes");break;case"go-users":go("usuarios");break;case"go-offline":go("offline");break;case"go-config":go("configuracion");break;
case"new-report":go("informes");toast("Selecciona filtros para generar el informe");break;case"generate-report":toast("Informe de demostración preparado");break;
case"layers":dialog("Capas cartográficas",`<div>${["Tramos de caminos","Incidencias","Intervenciones","Infraestructura","Inspecciones","Límite regional","Imágenes satelitales"].map(x=>`<label class="settings-row"><input type="checkbox" checked> <span class="setting-copy"><b>${x}</b><small>Visibilidad de capa</small></span></label>`).join("")}</div>`,`<button class="btn" data-close>Cerrar</button><button class="btn primary" data-action="confirm">Aplicar capas</button>`);break;
case"center":toast("Vista esquemática centrada");break;case"zoom":toast("Zoom visual; mapa no georreferenciado");break;
case"sync":dialog("Sincronización",`<div class="note">Esta vista es una representación del flujo offline. No hay servidor remoto conectado.</div><div class="progress-row"><span>Elementos locales en espera</span><b>12</b></div><div class="progress"><span style="width:75%"></span></div><p>La siguiente fase incorporará cola persistente, reintentos y resolución de conflictos.</p>`,`<button class="btn" data-close>Entendido</button>`);break;
case"offline-settings":dialog("Configuración offline",`<div>${settingsRow("☁","Guardar registros en el dispositivo","Preparación de modo offline","Activo")}${settingsRow("↻","Sincronización automática","Backend pendiente","Pendiente")}${settingsRow("♧","Notificaciones","Avisos de sincronización","Activo")}</div>`);break;
case"conflicts":dialog("Conflictos de sincronización",`<div class="note">Conflictos ilustrativos; no hay versión remota para comparar.</div>${records.filter(r=>r.tone==="danger").map(r=>activity("△",r.code,r.name,"Pendiente","red")).join("")}`);break;
case"download-map":toast("Proveedor cartográfico no conectado");break;case"clear-local":dialog("Limpiar datos locales",`<div class="note">No se borrarán registros principales. La limpieza real se implementará en la fase offline.</div>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger-btn" data-action="confirm">Confirmar</button>`);break;
case"save-config":toast("Preferencias visuales evaluadas; no hay backend");break;case"add-source":toast("Conexión de proveedores pendiente");break;
case"backup":exportFile("geotracia-demo-backup.json",JSON.stringify({records,users},null,2),"application/json");toast("Respaldo JSON descargado");break;
case"reset":dialog("Restaurar datos demo",`<div class="note">Se restaurarán los datos iniciales en este navegador.</div>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger-btn" data-action="confirm-reset">Restaurar</button>`);break;
case"confirm-reset":records=structuredClone(initial);users=structuredClone(initialUsers);save();$("#dialog").close();show();toast("Datos demo restaurados");break;
case"new-subscription":dialog("Nueva suscripción",`<form id="subForm" class="form-grid">${field("Organización","subOrg","Nombre de organización")}<div><label class="field-label">Plan</label><select class="field"><option>Básico</option><option>Profesional</option><option>Empresa</option></select></div>${field("Fecha de inicio","subStart","","")}${field("Fecha de término","subEnd","","") }<div class="note full">No se ejecutan cobros ni se activan licencias en este prototipo.</div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="validate-sub">Validar</button>`);break;
case"validate-sub":if(!$("#subForm").reportValidity())return;$("#dialog").close();toast("Formulario validado; facturación pendiente");break;
case"subscription-detail":dialog("Detalle de suscripción",`<div class="note">Datos de muestra, sin conexión con facturación.</div>${settingsRow("▦","Municipalidad de Ejemplo","Organización de referencia","Activo")}${settingsRow("▤","Plan Empresa","Precio ilustrativo","")}${settingsRow("▦","Vigencia","20 oct 2026 — 20 oct 2027","")}`);break;
case"select-plan":toast("Plan seleccionado para revisión; no se contrató ni cobró");break;
case"export-pdf":toast("Exportación PDF pendiente de integrar");break;case"export-kml":toast("Exportación geoespacial pendiente");break;
case"templates":dialog("Plantillas de informes",`<div>${settingsRow("▤","Estado de la red vial","Inspecciones, incidencias y mantenimiento")}${settingsRow("△","Incidencias y seguridad vial","Eventos y prioridades")}${settingsRow("⚒","Avance de mantenimiento","Intervenciones programadas")}</div>`);break;
case"clear-report":toast("Filtros restablecidos");break;case"roles":dialog("Roles y permisos",`<div class="note">Matriz visual de referencia; autorización real debe validarse en servidor.</div>${modules.map(m=>settingsRow(m[2],m[1],"Acceso sujeto a rol")).join("")}`);break;
case"invite":newUser();toast("El correo de invitación no está conectado");break;case"audit":dialog("Auditoría de demostración",`${activity("⚙","Preferencias consultadas","Configuración","Ahora")}${activity("♙","Directorio revisado","Usuarios","Hace 5 min")}${activity("▤","Registros consultados","Inspecciones","Hace 12 min")}`);break;
case"payment":case"invoices":case"usage":toast("Función administrativa demostrativa; sin transacciones reales");break;
case"import-road":toast("Importación de archivos pendiente de implementar");break;case"road-detail":dialog("Ficha del camino · R-720",`<div class="form-grid">${[["Código","R-720"],["Nombre","Ruta R-720"],["Región","La Araucanía"],["Longitud","42,6 km"],["Referencia","WGS 84"],["Estado","Activo"]].map(r=>`<div><label class="field-label">${r[0]}</label><p>${r[1]}</p></div>`).join("")}</div>`);break;
case"confirm-delete":records=records.filter(r=>r.code!==e.dataset.code);save();$("#dialog").close();show();toast("Registro eliminado localmente");break;
case"edit-record":editRecord(e.dataset.code);break;
case"confirm":$("#dialog").close();toast("Acción aplicada en la interfaz");break;
default:toast("Acción de demostración; integración real pendiente");
}}
document.addEventListener("submit",e=>{if(e.target.id==="orgCreateForm"){e.preventDefault();const n=$("#orgCreateName").value.trim();if(n.length>=2)createGeoOrganization(n)}if(e.target.id==="projectForm"){e.preventDefault();saveGeoProject($("[data-action=save-project]")?.dataset.projectId||"")}});
document.addEventListener("click",e=>{
let projectEdit=e.target.closest("[data-project-edit]");if(projectEdit){const p=geoProjects.find(x=>x.id===projectEdit.dataset.projectEdit);if(p)newProject(p);return}
let projectDelete=e.target.closest("[data-project-delete]");if(projectDelete){archiveGeoProject(projectDelete.dataset.projectDelete);return}
let goBtn=e.target.closest("[data-go]");if(goBtn){go(goBtn.dataset.go);return}
let view=e.target.closest("[data-view]");if(view){viewRecord(view.dataset.view);return}
let edit=e.target.closest("[data-edit]");if(edit){editRecord(edit.dataset.edit);return}
let del=e.target.closest("[data-delete]");if(del){dialog("Eliminar registro",`<div class="note">Esta acción elimina el registro del almacenamiento local.</div><p>¿Eliminar ${esc(del.dataset.delete)}?</p>`,`<button class="btn" data-close>Cancelar</button><button class="btn danger-btn" data-action="confirm-delete" data-code="${esc(del.dataset.delete)}">Eliminar</button>`);return}
let ue=e.target.closest("[data-user-edit]");if(ue){newUser(users.find(u=>u.email===ue.dataset.userEdit));return}
let ut=e.target.closest("[data-user-toggle]");if(ut){userToggle(ut.dataset.userToggle);return}
let t=e.target.closest("[data-tab]");if(t){tab=t.dataset.tab;$$(".tab").forEach(b=>b.classList.toggle("active",b===t));$("#tabBody").innerHTML=tabContent(tab);return}
let a=e.target.closest("[data-action]");if(a){act(a.dataset.action,a);return}
if(e.target.closest("[data-close]"))$("#dialog").close();
});
document.addEventListener("input",e=>{
if(e.target.id==="tableSearch"){query=e.target.value;let d=records.filter(r=>match(r,query)&&(!typeFilter||r.type===typeFilter));let t=$("#recordsTable");if(t)t.innerHTML=table(d); }
if(e.target.id==="userSearch"){query=e.target.value;let t=$("#userTable");if(t)t.innerHTML=userTable()}
if(e.target.id==="roadSearch")$$('#roadRows tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(e.target.value.toLowerCase()));
if(e.target.id==="globalSearch"&&e.target.value.trim().length>1){let q=e.target.value.toLowerCase(),m=modules.find(x=>x[1].toLowerCase().includes(q));if(m){/* search remains unobtrusive until Enter */}}
});
document.addEventListener("change",e=>{if(e.target.id==="typeFilter"){typeFilter=e.target.value;let t=$("#recordsTable");if(t)t.innerHTML=table(records.filter(r=>match(r,query)&&(!typeFilter||r.type===typeFilter)))}if(e.target.id==="userState"){let t=$("#userTable");if(t)t.innerHTML=userTable()}});
$("#globalSearch").addEventListener("keydown",e=>{if(e.key==="Enter"){let q=e.target.value.trim().toLowerCase(),m=modules.find(x=>x[1].toLowerCase().includes(q)||x[3].toLowerCase().includes(q));if(m)go(m[0]);else{query=q;go("inspecciones");toast("Búsqueda aplicada a registros")}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();e.target.focus()}});
$("#menu").addEventListener("click",()=>{$("#sidebar").classList.toggle("open");$("#overlay").classList.toggle("show")});$("#overlay").addEventListener("click",()=>{$("#sidebar").classList.remove("open");$("#overlay").classList.remove("show")});
$("#notifications").addEventListener("click",()=>dialog("Notificaciones",activity("△","Incidencia crítica pendiente","INC-2026-067 · Desprendimiento de talud","Hace 2 h","red")+activity("☑","Inspección completada","INS-2026-028 · Ruta R-720","Hoy · 14:32","teal")+activity("☁","Entorno de demostración","No hay sincronización externa","Ahora")));
$("#help").addEventListener("click",()=>dialog("Centro de ayuda",`<p>Este prototipo permite evaluar navegación, distribución, formularios, filtros, vistas responsive y operaciones locales.</p><div class="note">No incluye aún autenticación real, base de datos compartida, GPS, mapas georreferenciados ni sincronización con servidor.</div>`));
$("#project").addEventListener("click",()=>dialog("Proyecto activo",settingsRow("⌁","Ruta R-720 - Conservación 2024","La Araucanía","Activo")+settingsRow("⌁","Ruta S-51","Proyecto de referencia","Pendiente")));
document.addEventListener("keydown",e=>{if(e.key==="Escape"){$("#sidebar").classList.remove("open");$("#overlay").classList.remove("show")}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();$("#globalSearch").focus()}});
show();
window.addEventListener("geotracia:session",()=>{if(active==="proyectos")loadGeoProjects()});
})();